{
  "implementation": "def solve(case):
    segs = case['segments']
    budget = case['budget']
    n = len(segs)
    mins = [seg['minimum'] for seg in segs]
    caps = [seg['capacity'] for seg in segs]
    # Validate
    total_min = sum(mins)
    total_cap = sum(caps)
    if budget < total_min or budget > total_cap:
        # fallback (should not happen per spec, but provide safe output)
        return {'allocations': [0]*n, 'by_name': {seg['name']:0 for seg in segs}, 'total': 0}
    alloc = mins[:]  # copy
    remaining = budget - total_min
    while remaining > 0:
        best_i = -1
        best_val = -1.0
        for i, seg in enumerate(segs):
            if alloc[i] < caps[i]:
                val = seg['importance'] / (alloc[i] + 1)
                if val > best_val:
                    best_val = val
                    best_i = i
        # tie? if equal, first encountered (since we iterate in order, > ensures earlier wins on equal? Actually we use > not >=, so if later equal, it won't replace. But tie-breaking spec says original order. Since we iterate in order, > will keep first when equal because later equal won't be >. Good.
        if best_i == -1:
            break  # shouldn't happen if budget <= total_cap
        alloc[best_i] += 1
        remaining -= 1
    by_name = {segs[i]['name']: alloc[i] for i in range(n)}
    return {'allocations': alloc, 'by_name': by_name, 'total': sum(alloc)}
